// Resumen de las ventas de ayer. «Ayer» se calcula con la zona horaria de n8n (Settings > Timezone).
// Cambia MONEDA si vendes en otra moneda (por ejemplo 'USD' o 'MXN'): solo afecta al formato del correo.
const MONEDA = 'COP';
const LOCALE = 'es-CO';

const ayer = $now.minus({ days: 1 });
const ayerISO = ayer.toFormat('yyyy-MM-dd');

// Fecha de la fila → AAAA-MM-DD. Acepta:
// - número de serie de Sheets (celda de fecha real; «Leer ventas» la entrega así, sin depender del idioma de la hoja)
// - texto AAAA-MM-DD o DD/MM/AAAA
function aISO(valor) {
  if (typeof valor === 'number') {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Math.floor(valor) }).toFormat('yyyy-MM-dd');
  }
  const texto = String(valor ?? '').trim();
  const dma = texto.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (dma) return dma[3] + '-' + dma[2].padStart(2, '0') + '-' + dma[1].padStart(2, '0');
  return texto.slice(0, 10);
}

// Total → número. Los números se usan tal cual. El texto se lee con formato colombiano:
// «$ 45.000», «45.000» o «45.000,50» (punto de miles, coma decimal). Si no se puede leer, devuelve null.
function aNumero(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : null;
  const limpio = String(valor ?? '')
    .replace(/\$/g, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  if (limpio === '') return null;
  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}

const ventas = $input.all()
  .map((item) => item.json)
  .filter((fila) => aISO(fila.Fecha) === ayerISO);

// Las filas con Total ilegible no se suman en silencio: se cuentan y se avisan en el correo
let total = 0;
let filasInvalidas = 0;
const veces = {};
const ingresos = {};
for (const fila of ventas) {
  const producto = String(fila.Producto || 'Sin producto');
  veces[producto] = (veces[producto] || 0) + 1;
  const monto = aNumero(fila.Total);
  if (monto === null) {
    filasInvalidas++;
    continue;
  }
  // Las devoluciones (montos negativos) restan del total y del ingreso del producto
  total += monto;
  ingresos[producto] = (ingresos[producto] || 0) + monto;
}

const primero = (conteo) => Object.entries(conteo).sort((a, b) => b[1] - a[1])[0];
const [masVendido, nVentas] = primero(veces) ?? ['', 0];
const [mayorIngreso, ingresoMayor] = primero(ingresos) ?? ['', 0];

const dinero = (n) => new Intl.NumberFormat(LOCALE, { style: 'currency', currency: MONEDA, maximumFractionDigits: 0 }).format(n);
const dia = ayer.setLocale('es').toFormat("cccc d 'de' LLLL");
const aviso = filasInvalidas > 0
  ? 'Atención: ' + filasInvalidas + (filasInvalidas === 1 ? ' fila con Total no válido no se sumó.' : ' filas con Total no válido no se sumaron.') + ' Revisa la columna Total en la hoja.'
  : '';

const asunto = ventas.length === 0
  ? 'Reporte de ventas: sin ventas el ' + dia
  : 'Reporte de ventas del ' + dia + ': ' + ventas.length + ' ventas, ' + dinero(total);

const cuerpo = ventas.length === 0
  ? 'Ayer (' + dia + ') no se registraron ventas en la hoja.\n\nSi esperabas ventas, revisa que la columna Fecha tenga una fecha real o el formato AAAA-MM-DD.'
  : [
      'Resumen de ventas del ' + dia + ':',
      '',
      'Ventas: ' + ventas.length,
      'Total: ' + dinero(total),
      'Más vendido (por cantidad de ventas): ' + masVendido + ' (' + nVentas + (nVentas === 1 ? ' venta)' : ' ventas)'),
      ...(mayorIngreso ? ['Mayor ingreso: ' + mayorIngreso + ' (' + dinero(ingresoMayor) + ')'] : []),
      ...(aviso ? ['', aviso] : []),
    ].join('\n');

return [{ json: { asunto, cuerpo, ventas: ventas.length, total, filasInvalidas } }];
